import json
import os
import sys
import time
import webbrowser
from typing import Optional

from .secure_api import get_client_id, poll_login, get_model_info, open_sso_login

AHCLAUDE_DIR = os.path.expanduser("~/.ahdev")
AUTH_CACHE_FILE = os.path.join(AHCLAUDE_DIR, "auth.json")
LOG_FILE = os.path.join(AHCLAUDE_DIR, "hook.log")

def log_error(msg: str):
    print(f"\n\033[31m[错误] {msg}\033[0m", file=sys.stderr)


def log_warning(msg: str):
    print(f"\n\033[33m[警告] {msg}\033[0m")


def log_success(msg: str):
    print(f"\033[32m{msg}\033[0m")


def load_auth_cache() -> dict:
    if not os.path.exists(AUTH_CACHE_FILE):
        return {}
    try:
        with open(AUTH_CACHE_FILE, "r", encoding="utf-8") as f:
            return json.load(f)
    except json.JSONDecodeError as e:
        log_warning(f"认证缓存文件格式错误，已忽略: {e}")
        return {}
    except IOError as e:
        log_warning(f"读取认证缓存失败，已忽略: {e}")
        return {}


def save_auth_cache(auth: dict):
    try:
        os.makedirs(AHCLAUDE_DIR, exist_ok=True)
        with open(AUTH_CACHE_FILE, "w", encoding="utf-8") as f:
            json.dump(auth, f, ensure_ascii=False, indent=2)
    except IOError as e:
        log_error(f"保存认证缓存失败: {e}")
        raise


def is_logged_in() -> bool:
    auth = load_auth_cache()
    return auth.get("loggedIn", False) and bool(auth.get("username"))


def login() -> dict:
    print("[1/4] 获取登录信息...")
    try:
        client_id = get_client_id()
    except Exception as e:
        log_error(f"登录流程中断: {e}")
        raise

    sso_url = open_sso_login(client_id)
    print("[2/4] 打开浏览器登录页面...")
    print(f"      如未自动打开，请手动访问: {sso_url}")
    try:
        webbrowser.open(sso_url)
    except Exception as e:
        log_warning(f"无法自动打开浏览器，请手动访问: {sso_url}")

    print("[3/4] 等待扫码授权...")
    try:
        user_info = poll_login(client_id)
        print()
    except TimeoutError:
        raise

    username = user_info.get("adAccount") or user_info.get("username") or user_info.get("user_id", "")
    if not username:
        log_warning("无法获取用户名，使用默认值")
        username = "unknown"

    auth = {
        "loggedIn": True,
        "username": username,
        "lastLoginTime": int(time.time() * 1000),
        "userInfo": user_info,
    }
    try:
        save_auth_cache(auth)
        log_success(f"      登录成功: {username}")
    except IOError:
        raise

    print("[4/4] 获取模型配置...")
    model_info = get_model_info(username)

    # 保存 token 到 auth.json
    auth["token"] = model_info["token"]
    save_auth_cache(auth)

    return {
        "username": username,
        "token": model_info["token"],
        "api_key": model_info["api_key"],
        "model": model_info["models"][0] if model_info["models"] else "baidu-deepseek-v3.1-ab",
        "models": model_info["models"],
        "model_names": model_info.get("model_names", {}),
    }


def ensure_login() -> dict:
    if is_logged_in():
        auth = load_auth_cache()
        username = auth.get("username", "")
        print(f"[1/2] 已登录: {username}")

        print("[2/2] 获取模型配置...")
        model_info = get_model_info(username)

        # 更新 auth.json 中的 token
        auth["token"] = model_info["token"]
        save_auth_cache(auth)

        return {
            "username": username,
            "token": model_info["token"],
            "api_key": model_info["api_key"],
            "model": model_info["models"][0] if model_info["models"] else "baidu-deepseek-v3.1-ab",
            "models": model_info["models"],
            "model_names": model_info.get("model_names", {}),
        }

    return login()
